  `wave` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `sea_state_shift` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `wave_shift` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `advisory` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
