--
-- Table structure for table `tbl_forecast_general_old_wimp`
--

DROP TABLE IF EXISTS `tbl_forecast_general_old_wimp`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_forecast_general_old_wimp` (
  `id` int NOT NULL AUTO_INCREMENT,
  `forecast_date` date NOT NULL,
  `forecast_time` time DEFAULT NULL,
  `forecast_type` int DEFAULT NULL,
  `general_situation` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `thr_forecast` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `wind_speed` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `wind_direction` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `wind_condition` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `wind_shift_speed` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `wind_shift_direction` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `wind_shift_condition` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `sea_state` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `advisory` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `outlook` varchar(1000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `coast_high_f` int NOT NULL,
  `coast_high_c` int DEFAULT NULL,
  `coast_low_f` int NOT NULL,
  `coast_low_c` int DEFAULT NULL,
  `inland_high_f` int NOT NULL,
  `inland_high_c` int DEFAULT NULL,
  `inland_low_f` int NOT NULL,
  `inland_low_c` int DEFAULT NULL,
  `hills_high_f` int NOT NULL,
  `hills_high_c` int DEFAULT NULL,
  `hills_low_f` int NOT NULL,
  `hills_low_c` int DEFAULT NULL,
  `publish_to_web` tinyint(1) NOT NULL,
  `forecaster_id` int NOT NULL,
  `created_by` varchar(11) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `created_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `updated_by` int NOT NULL,
  `updated_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `state` (`publish_to_web`) USING BTREE,
  KEY `created_by` (`created_by`) USING BTREE,
  KEY `modified_by` (`updated_by`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=3415 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

